script:
(function () {
  'use strict';
  // Business loan payment, total cost, APR including fees and optional debt service coverage.
  //   Periodic rate i = annual rate / payments per year; N = term in years * payments per year.
  //   Payment: PMT = L * i / (1 - (1 + i)^-N) (PMT = L / N at 0%).
  //   Fees = origination % * L + other fees. APR = the yearly rate that makes the present value of
  //   the payments equal the amount received after fees (L - fees), found by bisection, times
  //   payments per year (the US Truth in Lending convention).
  //   DSCR = annual net operating income / (annual new-loan payments + other annual debt payments).
  // Verified in Node (scratchpad tests): $10,000 at 10% for 5 yrs monthly = $212.47, total interest
  //   $2,748.23 (cross-checked with a published calculator's default); APR with $1,250 fees =
  //   15.933% by exact solve (the published calculator shows 15.931%, a rounding difference);
  //   $100,000 at 9% for 5 yrs = $2,075.84/mo; no fees gives APR = rate; 0% with no fees gives 0%;
  //   no NaN/Infinity on blank or bad input.
  var money = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 2 });
  var FREQ = { '52': 'week', '26': 'two weeks', '24': 'half month', '12': 'month', '4': 'quarter', '1': 'year' };
  var last = null;

  function el(id) { return document.getElementById(id); }

  function read(id, blankAsZero) {
    var raw = String(el(id).value).trim();
    if (raw === '') return blankAsZero ? 0 : NaN;
    var v = Number(raw);
    return isFinite(v) ? v : NaN;
  }

  function payment(principal, i, n) {
    if (n <= 0 || principal <= 0) return 0;
    if (i === 0) return principal / n;
    return principal * i / (1 - Math.pow(1 + i, -n));
  }

  function presentValue(pmt, i, n) {
    return i === 0 ? pmt * n : pmt * (1 - Math.pow(1 + i, -n)) / i;
  }

  // Periodic rate at which the payments are worth exactly `received` today.
  function solveRate(pmt, n, received) {
    if (received <= 0 || pmt <= 0) return NaN;
    if (presentValue(pmt, 0, n) <= received) return 0;
    var lo = 0, hi = 1;
    while (presentValue(pmt, hi, n) > received && hi < 1e6) hi *= 2;
    for (var k = 0; k < 200; k++) {
      var mid = (lo + hi) / 2;
      if (presentValue(pmt, mid, n) > received) lo = mid; else hi = mid;
    }
    return (lo + hi) / 2;
  }

  function schedule(loan, i, n, pmt) {
    var bal = loan, rows = [], total = 0;
    for (var k = 1; k <= n; k++) {
      var interest = bal * i;
      var principal = k === n ? bal : Math.min(pmt - interest, bal);
      bal -= principal;
      if (bal < 0.005) bal = 0;
      total += interest;
      rows.push({ n: k, interest: interest, principal: principal, balance: bal });
    }
    return { rows: rows, totalInterest: total };
  }

  function setText(id, text) { el(id).textContent = text; }

  function clearResults() {
    ['blPayment', 'blTotalInterest', 'blApr', 'blTotalCost', 'blTotalFees', 'blReceived', 'blTotalPayments',
     'blCount', 'blAnnualDebt', 'blDscr'].forEach(function (id) { setText(id, '–'); });
    setText('blPaymentLabel', 'Payment');
    setText('blDscrNote', '');
    el('blSchedule').innerHTML = '';
    last = null;
  }

  function update() {
    var loan = read('blAmount'), rate = read('blRate'), years = read('blYears', true), months = read('blMonths', true),
        ppy = parseInt(el('blFrequency').value, 10), origination = read('blOrigination', true),
        otherFees = read('blFees', true), noi = read('blIncome', true), otherDebt = read('blOtherDebt', true);
    var n = Math.round((years * 12 + months) * ppy / 12);
    var error = el('blError'), msg = '';
    if (isNaN(loan) || loan <= 0) msg = 'Enter a loan amount greater than $0.';
    else if (isNaN(rate) || rate < 0 || rate > 100) msg = 'Enter an interest rate from 0% to 100%.';
    else if (isNaN(years) || isNaN(months) || years < 0 || months < 0 || years % 1 !== 0 || months % 1 !== 0 || months > 11 || years * 12 + months < 1 || years > 40) msg = 'Enter the term as whole years (up to 40) and months (0 to 11).';
    else if (n < 1) msg = 'The term is shorter than one payment period. Lengthen the term or pay more often.';
    else if ([origination, otherFees, noi, otherDebt].some(function (v) { return isNaN(v) || v < 0; })) msg = 'Fees, income and debt payments cannot be negative.';
    else if (origination > 20) msg = 'Enter an origination fee of 20% or less.';
    else if (loan * origination / 100 + otherFees >= loan) msg = 'Fees must be less than the loan amount.';
    error.hidden = !msg;
    error.textContent = msg;
    if (msg) { clearResults(); return; }

    var i = rate / 100 / ppy;
    var pmt = payment(loan, i, n);
    var s = schedule(loan, i, n, pmt);
    var fees = loan * origination / 100 + otherFees;
    var apr = solveRate(pmt, n, loan - fees) * ppy * 100;
    var annualDebt = pmt * ppy;

    setText('blPaymentLabel', 'Payment every ' + FREQ[String(ppy)]);
    setText('blPayment', money.format(pmt));
    setText('blTotalInterest', money.format(s.totalInterest));
    setText('blApr', isFinite(apr) ? apr.toFixed(3) + '%' : '–');
    setText('blTotalCost', money.format(s.totalInterest + fees));
    setText('blTotalFees', money.format(fees));
    setText('blReceived', money.format(loan - fees));
    setText('blTotalPayments', money.format(loan + s.totalInterest));
    setText('blCount', String(n));
    setText('blAnnualDebt', money.format(annualDebt));
    if (noi > 0) {
      var dscr = noi / (annualDebt + otherDebt);
      setText('blDscr', dscr.toFixed(2));
      setText('blDscrNote', dscr >= 1.25 ? 'At or above 1.25, a common lender minimum.' :
        (dscr >= 1 ? 'Income covers the payments, but below the 1.25 many lenders look for.' : 'Income does not cover the yearly debt payments.'));
    } else {
      setText('blDscr', '–');
      setText('blDscrNote', 'Enter yearly net operating income to see this ratio.');
    }
    last = { rows: s.rows, ppy: ppy };
    renderSchedule();
  }

  function renderSchedule() {
    var body = el('blSchedule');
    if (!last) { body.innerHTML = ''; return; }
    var html = [], p = 0, intr = 0, ppy = last.ppy, rows = last.rows;
    rows.forEach(function (row, idx) {
      p += row.principal; intr += row.interest;
      if (row.n % ppy === 0 || idx === rows.length - 1) {
        html.push('<tr><td>' + Math.ceil(row.n / ppy) + '</td><td>' + money.format(p + intr) + '</td><td>' + money.format(p) +
          '</td><td>' + money.format(intr) + '</td><td>' + money.format(row.balance) + '</td></tr>');
        p = 0; intr = 0;
      }
    });
    body.innerHTML = html.join('');
  }

  document.addEventListener('DOMContentLoaded', function () {
    var form = el('blForm');
    if (!form) return;
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    update();
  });
})();
